import{I as t,o as r,c as l,b6 as i,J as h,w as u,j as e,a as d}from"./chunks/framework.BUXTSoD9.js";const g=JSON.parse('{"title":"The Mom Test: Wie man Bed&uuml;rfnisse durch Nutzerinterviews validiert","description":"Ein Einf&uuml;hrungsartikel zu The Mom Test f&uuml;r Einsteiger. Lernen Sie, h&ouml;fliches Feedback zu vermeiden und Nutzerinterviews auf der Basis echten Verhaltens, konkreter Fakten und bestehender Probleme durchzuf&uuml;hren.","frontmatter":{"title":"The Mom Test: Wie man Bed&uuml;rfnisse durch Nutzerinterviews validiert","description":"Ein Einf&uuml;hrungsartikel zu The Mom Test f&uuml;r Einsteiger. Lernen Sie, h&ouml;fliches Feedback zu vermeiden und Nutzerinterviews auf der Basis echten Verhaltens, konkreter Fakten und bestehender Probleme durchzuf&uuml;hren."},"headers":[],"relativePath":"de-de/stage-1/appendix-mom-test/index.md","filePath":"de-de/stage-1/appendix-mom-test/index.md"}'),c={name:"de-de/stage-1/appendix-mom-test/index.md"},b=Object.assign(c,{setup(o){const s="Etwa <strong>1,5 Stunden</strong>";return(p,n)=>{const a=t("ChapterIntroduction");return r(),l("div",null,[n[1]||(n[1]=i('<h1 id="the-mom-test-wie-man-bed-uuml-rfnisse-durch-nutzerinterviews-validiert" tabindex="-1">The Mom Test: Wie man Bedürfnisse durch Nutzerinterviews validiert <a class="header-anchor" href="#the-mom-test-wie-man-bed-uuml-rfnisse-durch-nutzerinterviews-validiert" aria-label="Permalink to “The Mom Test: Wie man Bed&amp;uuml;rfnisse durch Nutzerinterviews validiert”">​</a></h1><p><a id="top-mom"></a></p><h2 id="kapitel-uuml-bersicht" tabindex="-1">Kapitelübersicht <a class="header-anchor" href="#kapitel-uuml-bersicht" aria-label="Permalink to “Kapitel&amp;uuml;bersicht”">​</a></h2>',3)),h(a,{duration:s,tags:["Nutzerinterviews","Bedarfsvalidierung","Nutzerforschung","Produktrecherche"],coreOutput:"1 Satz Interview-Fragen, die echte Informationen zutage fördern",expectedOutput:"Nutzerhöflichkeit nicht mehr als Validierung betrachten und stattdessen echtes Verhalten zur Richtungsbewertung nutzen"},{default:u(()=>[...n[0]||(n[0]=[e("p",null,'Viele denken beim ersten Mal, wenn sie eine Produktrecherche durchführen, das Wichtigste sei "mit jemandem zu sprechen". Also fragen sie Freunde, Kollegen oder sogar Familienmitglieder:',-1),e("ul",null,[e("li",null,"Was hältst du von meiner Idee?"),e("li",null,"Würdest du ein solches Produkt nutzen, wenn es gäbe?"),e("li",null,"Klingt diese Funktion nicht ganz gut?")],-1),e("p",null,"Die anderen geben dann oft sehr ermutigendes Feedback:",-1),e("ul",null,[e("li",null,"Das ist toll"),e("li",null,"Klingt sehr nützlich"),e("li",null,"Ich denke, du könntest es ausprobieren")],-1),e("p",null,'Das Problem ist, dass diese Antworten Ihnen in der Regel nicht bei der Entscheidungsfindung helfen. Sie sind eher Höflichkeit, Unterstützung oder eine natürliche Reaktion, um Ihnen nicht den Wind aus den Segeln zu nehmen. Sie denken, Sie hätten "Marktvalidierung" erhalten, aber tatsächlich haben Sie nur eine Reihe von schwer verwertbaren Trostpflastern gesammelt.',-1),e("p",null,[d("The Mom Test wurde genau entwickelt, um dieses Problem zu lösen. Es erinnert uns: "),e("strong",null,"Nutzer wollen Sie nicht absichtlich täuschen, sondern Ihre Frageweise führt sie natürlich zu schönen, aber nutzlosen Antworten.")],-1)])]),_:1}),n[2]||(n[2]=i(`<div class="info custom-block"><p class="custom-block-title">Minimales SOP</p><p><strong>Ziel</strong>: Nach dem Lesen wissen Sie besser, wie Sie mit Nutzern sprechen, ohne nur &quot;klingt gut&quot; zu hören, sondern wirklich Informationen zu erhalten, die Ihnen bei der Richtungsbewertung helfen.</p><p><strong>Aktionspunkte</strong>: Ändern Sie Ihre ursprünglich geplanten 5 Fragen und priorisieren Sie &quot;Wann war das letzte Mal&quot; und &quot;Wie haben Sie das damals gelöst&quot;.</p><p><strong>Ergebnis</strong>: Sie können leichter unterscheiden, was Meinungen sind und was wirklich evidenzbasierte Erkenntnisse.</p><p><strong>Stichwortsprünge</strong>: <a href="#mom-what">Was ist The Mom Test</a> · <a href="#mom-principles">Drei Kernprinzipien</a> · <a href="#mom-ai">Wie AI Ihnen hilft</a></p></div><h2 id="was-sie-lernen-werden" tabindex="-1">Was Sie lernen werden <a class="header-anchor" href="#was-sie-lernen-werden" aria-label="Permalink to “Was Sie lernen werden”">​</a></h2><ol><li>Welches Problem The Mom Test eigentlich löst und warum viele &quot;Nutzerbefragungen&quot; keine echten Informationen liefern</li><li>Die wichtigsten Prinzipien dieser Methode: Weniger nach Meinungen fragen, mehr nach Verhalten; weniger nach Hypothesen, mehr nach Fakten</li><li>Wie man eine Frage, die leicht zu falsch-positivem Feedback führt, in eine wertvollere Interview-Frage umschreibt</li><li>Wie man The Mom Test mit JTBD, Bedarfsvalidierung und MVP-Bewertung verknüpft</li></ol><p><a id="mom-what"></a></p><h2 id="_1-was-ist-the-mom-test-uuml-berhaupt" tabindex="-1"><a href="#top-mom">1. Was ist The Mom Test überhaupt?</a> <a class="header-anchor" href="#_1-was-ist-the-mom-test-uuml-berhaupt" aria-label="Permalink to “1. Was ist The Mom Test &amp;uuml;berhaupt?”">​</a></h2><p>The Mom Test stammt aus dem gleichnamigen Buch von Rob Fitzpatrick. Der Name klingt wie ein Witz, trifft aber den Nagel auf den Kopf:</p><p><strong>Selbst Ihre Mutter wird Ihnen nur schwer direkt sagen: &quot;Das ist eine schlechte Idee.&quot;</strong></p><p>Der Grund ist nicht, dass sie nicht ehrlich ist, sondern:</p><ul><li>Sie will Sie nicht verletzen</li><li>Sie wird Sie unbewusst ermutigen</li><li>Sie neigt dazu, in Ihrem Ausdruck zu antworten</li></ul><p>Nicht nur Mütter, sondern auch Freunde, Kollegen, ehemalige Mitschüler und sogar viele Fremde geben oft ähnliches &quot;positives Feedback&quot;, wenn sie mit Ihrer Produktidee konfrontiert werden. Das bedeutet nicht, dass der Bedarf wirklich existiert, sondern nur, dass Sie die Frage so formuliert haben, dass sie leicht eine schöne Antwort provozieren.</p><p>Also geht es bei The Mom Test nie um &quot;Frag deine Mama nicht&quot;, sondern:</p><p><strong>Stellen Sie Ihre Fragen nicht so, dass jeder Ihnen zustimmt.</strong></p><p>Die Methode will Ihnen beibringen, wie Sie durch Gespräche Informationen erhalten, die näher an echten Bedürfnissen sind, anstatt eine Sammlung von sich gut anfühlenden Kommentaren zu sammeln.</p><h2 id="_2-welches-kernproblem-es-l-ouml-st" tabindex="-1">2. Welches Kernproblem es löst <a class="header-anchor" href="#_2-welches-kernproblem-es-l-ouml-st" aria-label="Permalink to “2. Welches Kernproblem es l&amp;ouml;st”">​</a></h2><p>The Mom Test löst hauptsächlich eine sehr häufige kognitive Täuschung:</p><p><strong>Höfliches positives Feedback als echten Bedarf zu betrachten.</strong></p><p>Wenn Sie fragen:</p><ul><li>Was hältst du von dieser App-Idee?</li><li>Würdest du ein AI-Tool nutzen, das dir beim Schreiben von Lebensläufen hilft?</li><li>Ist diese Funktion nicht sehr wertvoll?</li></ul><p>Diese Fragen haben gemeinsame Merkmale:</p><ul><li>Sie fragen nach &quot;Meinungen&quot;</li><li>Sie enthalten eine leichte Andeutung</li><li>Sie reden über eine Zukunft, die noch nicht eingetreten ist</li></ul><p>Und die Antworten auf &quot;Meinungen&quot; und &quot;zukünftige Hypothesen&quot; sind meist instabil. Viele Menschen überschätzen ihr Interesse, ihre Ausführungsbereitschaft und ihre zukünftige Zahlungsbereitschaft.</p><p>The Mom Test erinnert Sie daran:</p><ul><li>Vertrauen Sie nicht zu sehr auf die Bewertungen anderer zu Ihrer Idee</li><li>Vertrauen Sie nicht zu sehr auf die Vorhersagen anderer zu ihrem zukünftigen Verhalten</li><li>Kehren Sie möglichst zu dem zurück, was Nutzer bereits getan haben</li></ul><p>Denn im Vergleich zu &quot;Würden Sie es nutzen&quot; ist &quot;Wie haben Sie das letzte Mal damit umgegangen&quot; oft näher an der Wahrheit.</p><p><a id="mom-principles"></a></p><h2 id="_3-die-drei-wichtigsten-prinzipien" tabindex="-1"><a href="#top-mom">3. Die drei wichtigsten Prinzipien</a> <a class="header-anchor" href="#_3-die-drei-wichtigsten-prinzipien" aria-label="Permalink to “3. Die drei wichtigsten Prinzipien”">​</a></h2><p>Wenn Sie sich nur das Wichtigste merken möchten, starten Sie mit diesen drei Prinzipien.</p><h3 id="_3-1-weniger-uuml-ber-ihre-idee-reden-mehr-uuml-ber-die-echten-erfahrungen-des-nutzers" tabindex="-1">3.1 Weniger über Ihre Idee reden, mehr über die echten Erfahrungen des Nutzers <a class="header-anchor" href="#_3-1-weniger-uuml-ber-ihre-idee-reden-mehr-uuml-ber-die-echten-erfahrungen-des-nutzers" aria-label="Permalink to “3.1 Weniger &amp;uuml;ber Ihre Idee reden, mehr &amp;uuml;ber die echten Erfahrungen des Nutzers”">​</a></h3><p>In vielen ineffektiven Interviews wird zu Beginn die eigene Lösung vorgestellt, man erzählt, wie aufregend sie ist und welches Produkt man entwickeln will. Das Problem: Sobald Sie zu viel erzählen, schaltet der andere leicht in den &quot;Unterstützen&quot;- und &quot;Ermutigen&quot;-Modus.</p><p>Besser ist es, den Schwerpunkt auf die Erfahrungen des Gesprächspartners zu legen:</p><ul><li>Wann hatten Sie das letzte Mal dieses Problem?</li><li>Was haben Sie damals getan?</li><li>Wie haben Sie es schließlich gelöst?</li><li>Welcher Schritt war am mühsamsten?</li></ul><p>Diese Fragen führen das Gespräch natürlicher zurück zur Realität, anstatt bei imaginären Präferenzen zu bleiben.</p><h3 id="_3-2-weniger-nach-abstrakten-meinungen-fragen-mehr-nach-konkreten-fakten" tabindex="-1">3.2 Weniger nach abstrakten Meinungen fragen, mehr nach konkreten Fakten <a class="header-anchor" href="#_3-2-weniger-nach-abstrakten-meinungen-fragen-mehr-nach-konkreten-fakten" aria-label="Permalink to “3.2 Weniger nach abstrakten Meinungen fragen, mehr nach konkreten Fakten”">​</a></h3><p>&quot;Ich finde diese Funktion gut&quot;, &quot;Klingt gut&quot;, &quot;Scheint nützlich zu sein&quot; – diese Äußerungen sind zu abstrakt, um Produktentscheidungen zu leiten.</p><p>Wertvollere Informationen sehen eher so aus:</p><ul><li>Letzte Woche habe ich dafür 2 Stunden verschwendet</li><li>Aktuell kämpfe ich mit Excel und WeChat</li><li>Letzten Monat habe ich bereits für ein ähnliches Tool bezahlt</li><li>Meine größte Angst ist es, falsch zu machen, nicht langsam zu sein</li></ul><p>Das sind die Informationen, die Ihnen wirklich helfen, Problemstärke, Häufigkeit und Zahlungsbereitschaft zu beurteilen.</p><h3 id="_3-3-weniger-fragen-welche-l-ouml-sung-der-nutzer-will-mehr-beobachten-wie-er-aktuell-l-ouml-st" tabindex="-1">3.3 Weniger fragen, welche Lösung der Nutzer will, mehr beobachten, wie er aktuell löst <a class="header-anchor" href="#_3-3-weniger-fragen-welche-l-ouml-sung-der-nutzer-will-mehr-beobachten-wie-er-aktuell-l-ouml-st" aria-label="Permalink to “3.3 Weniger fragen, welche L&amp;ouml;sung der Nutzer will, mehr beobachten, wie er aktuell l&amp;ouml;st”">​</a></h3><p>Nutzer sind gut darin, ihre Schwierigkeiten zu beschreiben, aber nicht unbedingt darin, Lösungen zu entwerfen.</p><p>Wenn Sie fragen:</p><ul><li>Möchten Sie ein AI-Tool, das das automatisch für Sie erledigt?</li><li>Denken Sie, eine intelligente Funktion wäre hilfreich?</li></ul><p>Erhalten Sie meist nur eine vage Haltung zu einer Lösung, nicht den Bedarf selbst.</p><p>Bessere Fragen:</p><ul><li>Welche Methode nutzen Sie aktuell, um dieses Problem zu lösen?</li><li>Warum haben Sie sich für diese Vorgehensweise entschieden?</li><li>Was ist daran nicht gut genug?</li></ul><p>Die bestehenden Alternativlösungen zu verstehen, ist oft wichtiger als direkt zu fragen, &quot;was wollen Sie&quot;.</p><h2 id="_4-warum-menschen-ihnen-immer-sch-ouml-ne-aber-nutzlose-antworten-geben" tabindex="-1">4. Warum Menschen Ihnen immer schöne, aber nutzlose Antworten geben <a class="header-anchor" href="#_4-warum-menschen-ihnen-immer-sch-ouml-ne-aber-nutzlose-antworten-geben" aria-label="Permalink to “4. Warum Menschen Ihnen immer sch&amp;ouml;ne, aber nutzlose Antworten geben”">​</a></h2><p>Wenn Sie dies verstehen, werden Sie bei Interviews weniger Fehleinschätzungen machen.</p><h3 id="_4-1-menschen-sind-unbewusst-h-ouml-flich" tabindex="-1">4.1 Menschen sind unbewusst höflich <a class="header-anchor" href="#_4-1-menschen-sind-unbewusst-h-ouml-flich" aria-label="Permalink to “4.1 Menschen sind unbewusst h&amp;ouml;flich”">​</a></h3><p>Besonders wenn Ihr Gesprächspartner eine Beziehung zu Ihnen hat, wird er nur schwer direkt sagen:</p><ul><li>Diese Richtung klingt nicht vielversprechend</li><li>Ich würde es überhaupt nicht nutzen</li><li>Dieses Problem ist für mich nicht so wichtig</li></ul><p>Er wird eher sagen: &quot;Ganz gut&quot;, &quot;Man könnte es mal probieren&quot;.</p><h3 id="_4-2-menschen-uuml-bersch-auml-tzen-ihr-zuk-uuml-nftiges-ich" tabindex="-1">4.2 Menschen überschätzen ihr zukünftiges Ich <a class="header-anchor" href="#_4-2-menschen-uuml-bersch-auml-tzen-ihr-zuk-uuml-nftiges-ich" aria-label="Permalink to “4.2 Menschen &amp;uuml;bersch&amp;auml;tzen ihr zuk&amp;uuml;nftiges Ich”">​</a></h3><p>Viele glauben ernsthaft, sie würden in Zukunft:</p><ul><li>Disziplinierter sein</li><li>Lernbereiter sein</li><li>Zahlungsbereiter sein</li><li>Offener für neue Tools sein</li></ul><p>Also bedeutet &quot;Ich würde es nutzen, wenn es gäbe&quot; oft nicht, dass sie es wirklich tun werden.</p><h3 id="_4-3-ihre-frageweise-selbst-f-uuml-hrt-die-antwort" tabindex="-1">4.3 Ihre Frageweise selbst führt die Antwort <a class="header-anchor" href="#_4-3-ihre-frageweise-selbst-f-uuml-hrt-die-antwort" aria-label="Permalink to “4.3 Ihre Frageweise selbst f&amp;uuml;hrt die Antwort”">​</a></h3><p>Wenn Sie fragen:</p><ul><li>Ist meine Idee nicht ganz gut?</li><li>Ist diese Funktion für Sie nicht sehr hilfreich?</li></ul><p>Haben Sie heimlich die &quot;richtige Antwort&quot; in die Frage eingebaut.</p><p>Deshalb betont The Mom Test besonders: <strong>Machen Sie das Interview nicht zu einer Suche nach Bestätigung.</strong></p><h2 id="_5-direktvergleich-welche-fragen-leicht-ins-leere-f-uuml-hren-welche-wertvoller-sind" tabindex="-1">5. Direktvergleich: Welche Fragen leicht ins Leere führen, welche wertvoller sind <a class="header-anchor" href="#_5-direktvergleich-welche-fragen-leicht-ins-leere-f-uuml-hren-welche-wertvoller-sind" aria-label="Permalink to “5. Direktvergleich: Welche Fragen leicht ins Leere f&amp;uuml;hren, welche wertvoller sind”">​</a></h2><p>Diese Gegenüberstellung wird fast jeder Einsteiger nutzen.</p><table tabindex="0"><thead><tr><th>Leider nutzlose Fragen</th><th>Wertvollere Fragen</th></tr></thead><tbody><tr><td>Was hältst du von meiner Idee?</td><td>Wann hattest du das letzte Mal dieses Problem?</td></tr><tr><td>Würdest du dieses Produkt nutzen?</td><td>Wie löst du das aktuell?</td></tr><tr><td>Würdest du für diese Funktion bezahlen?</td><td>Hast du letztes Mal für dieses Problem Geld ausgegeben? Wofür?</td></tr><tr><td>Findest du diese Funktion wichtig?</td><td>Welcher Schritt in diesem Prozess ist am nervigsten, langsamsten oder beunruhigendsten?</td></tr><tr><td>Möchtest du ein AI-Tool, das das automatisch macht?</td><td>Warum hast du bisher noch keine bessere Lösung gefunden?</td></tr></tbody></table><p>Das Wichtigste an dieser Tabelle ist nicht der konkrete Satz, sondern die Richtung dahinter:</p><ul><li>Von Meinungen zu Fakten</li><li>Von der Zukunft zur Vergangenheit</li><li>Von Ihrer Lösung zum Problem des Nutzers</li></ul><h2 id="_6-eine-interview-struktur-die-einsteiger-sofort-nutzen-k-ouml-nnen" tabindex="-1">6. Eine Interview-Struktur, die Einsteiger sofort nutzen können <a class="header-anchor" href="#_6-eine-interview-struktur-die-einsteiger-sofort-nutzen-k-ouml-nnen" aria-label="Permalink to “6. Eine Interview-Struktur, die Einsteiger sofort nutzen k&amp;ouml;nnen”">​</a></h2><p>Wenn Sie jetzt sofort jemanden finden und sprechen möchten, können Sie in dieser Reihenfolge vorgehen.</p><h3 id="_6-1-er-ouml-ffnung-erkl-auml-ren-sie-dass-sie-lernen-nicht-verkaufen" tabindex="-1">6.1 Eröffnung: Erklären Sie, dass Sie lernen, nicht verkaufen <a class="header-anchor" href="#_6-1-er-ouml-ffnung-erkl-auml-ren-sie-dass-sie-lernen-nicht-verkaufen" aria-label="Permalink to “6.1 Er&amp;ouml;ffnung: Erkl&amp;auml;ren Sie, dass Sie lernen, nicht verkaufen”">​</a></h3><p>Zum Beispiel:</p><blockquote><p>Ich erforsche gerade, wie Leute mit solchen Problemen umgehen. Ich möchte die reale Situation verstehen, nicht etwas verkaufen.</p></blockquote><p>Diese Formulierung macht es dem Gesprächspartner leichter, die psychologische Last &quot;Ich muss positives Feedback geben&quot; abzulegen.</p><h3 id="_6-2-mit-dem-letzten-echten-erlebnis-beginnen" tabindex="-1">6.2 Mit dem letzten echten Erlebnis beginnen <a class="header-anchor" href="#_6-2-mit-dem-letzten-echten-erlebnis-beginnen" aria-label="Permalink to “6.2 Mit dem letzten echten Erlebnis beginnen”">​</a></h3><p>Beginnen Sie mit Fragen wie:</p><ul><li>Wann hatten Sie das letzte Mal dieses Problem?</li><li>Was ist damals passiert?</li><li>Was war Ihre erste Reaktion?</li></ul><p>Sobald das Gespräch in konkrete Ereignisse eintritt, steigt die Informationsqualität meist deutlich.</p><h3 id="_6-3-weiter-nach-verhalten-kosten-und-alternativl-ouml-sungen-fragen" tabindex="-1">6.3 Weiter nach Verhalten, Kosten und Alternativlösungen fragen <a class="header-anchor" href="#_6-3-weiter-nach-verhalten-kosten-und-alternativl-ouml-sungen-fragen" aria-label="Permalink to “6.3 Weiter nach Verhalten, Kosten und Alternativl&amp;ouml;sungen fragen”">​</a></h3><p>Weiterfragen:</p><ul><li>Welche Methode nutzen Sie aktuell zur Lösung?</li><li>Was ist das Unangenehmste an dieser Methode?</li><li>Wie viel Zeit, Geld oder Energie haben Sie dafür aufgewendet?</li><li>Haben Sie andere Methoden ausprobiert? Warum nicht weiter verwendet?</li></ul><h3 id="_6-4-erst-am-ende-schmerzintensit-auml-t-und-priorit-auml-t-bewerten" tabindex="-1">6.4 Erst am Ende Schmerzintensität und Priorität bewerten <a class="header-anchor" href="#_6-4-erst-am-ende-schmerzintensit-auml-t-und-priorit-auml-t-bewerten" aria-label="Permalink to “6.4 Erst am Ende Schmerzintensit&amp;auml;t und Priorit&amp;auml;t bewerten”">​</a></h3><p>Sie müssen nicht direkt nach &quot;Tut es weh?&quot; fragen. Sie können aus Details beurteilen:</p><ul><li>Tritt es häufig auf</li></ul><ul><li>Handelt er bereits aktiv, um Abhilfe zu schaffen</li><li>Ist er bereits bereit, dafür Kosten auf sich zu nehmen</li><li>Zeigt er beim Erzählen spürbare Emotionen</li></ul><p>All das ist nützlicher als die Frage &quot;Ist das Ihr Schmerzpunkt?&quot;.</p><h2 id="_7-ein-vollst-auml-ndigeres-beispiel" tabindex="-1">7. Ein vollständigeres Beispiel <a class="header-anchor" href="#_7-ein-vollst-auml-ndigeres-beispiel" aria-label="Permalink to “7. Ein vollst&amp;auml;ndigeres Beispiel”">​</a></h2><p>Angenommen, Sie möchten ein Produkt entwickeln: &quot;AI hilft Studierenden beim Umschreiben von Lebensläufen&quot;.</p><h3 id="falsche-frageweise" tabindex="-1">Falsche Frageweise <a class="header-anchor" href="#falsche-frageweise" aria-label="Permalink to “Falsche Frageweise”">​</a></h3><p>Sie fragen einen Kommilitonen:</p><blockquote><p>Ich möchte ein AI-Lebenslauf-Optimierungstool entwickeln. Was hältst du davon? Wenn es Lebensläufe automatisch an Stellen anpassen könnte, würdest du es nutzen?</p></blockquote><p>In diesem Fall wird der andere wahrscheinlich sagen:</p><ul><li>Klingt gut</li><li>Ich denke, das wäre nützlich</li></ul><ul><li>Wenn es kostenlos ist, würde ich es ausprobieren</li></ul><p>Diese Antworten helfen Ihnen kaum zu beurteilen, wie stark der Bedarf wirklich ist.</p><h3 id="bessere-frageweise" tabindex="-1">Bessere Frageweise <a class="header-anchor" href="#bessere-frageweise" aria-label="Permalink to “Bessere Frageweise”">​</a></h3><p>Sie könnten es so formulieren:</p><blockquote><p>Wann hast du zuletzt deinen Lebenslauf geändert? Warum musstest du ihn ändern? Wie hast du ihn geändert? Welcher Schritt war am schwierigsten? Hast du jemals jemanden gebeten, deinen Lebenslauf gegenzulesen? Hast du jemals Zeit oder viel Geld für deinen Lebenslauf aufgewendet?</p></blockquote><p>Durch diese Fragen könnten Sie folgende Informationen erhalten:</p><ul><li>Viele können nicht schreiben, sondern wissen nicht, wie sie ihn auf verschiedene Stellen anpassen sollen</li></ul><ul><li>Ihr größter Schmerz ist nicht das Layout, sondern &quot;nicht zu wissen, welche Erfahrungen erwähnenswert sind&quot;</li><li>Sie schieben auf, nicht aus Faulheit, sondern weil jeder Lebenslauf-Änderungsprozess extrem erschöpfend ist</li><li>Sie behelfen sich bereits mit Ratschlägen von älteren Kommilitonen, Vorlagen-Websites, AI-Tools und Freunden als Gegenleser</li></ul><p>Jetzt sind Sie dem echten Problem viel näher.</p><h2 id="_8-wie-the-mom-test-und-jtbd-zusammenarbeiten" tabindex="-1">8. Wie The Mom Test und JTBD zusammenarbeiten <a class="header-anchor" href="#_8-wie-the-mom-test-und-jtbd-zusammenarbeiten" aria-label="Permalink to “8. Wie The Mom Test und JTBD zusammenarbeiten”">​</a></h2><p>Wenn JTBD Ihnen hilft zu erkennen, &quot;welchen Fortschritt Nutzer erzielen wollen&quot;, lehrt The Mom Test Sie eher:</p><p><strong>Wie Sie durch Interviews bestätigen, ob dieser Job wirklich existiert.</strong></p><p>Sie können beide Methoden nahtlos verknüpfen:</p><ol><li>Zunächst mit JTBD einen Job hypothetisieren</li><li>Dann mit The Mom Test bei Nutzern nach ihren letzten echten Erlebnissen fragen</li><li>Prüfen, ob dieser Job wirklich häufig, echt und priorisierbar ist</li></ol><p>Wenn Ihre JTBD-Hypothese beispielsweise lautet:</p><blockquote><p>Wenn ich mich auf ein Praktikum bewerbe, möchte ich meinen alten Lebenslauf schnell in eine Version umschreiben, die zur Stelle passt, um die Bewerbung so bald wie möglich abzuschicken.</p></blockquote><p>Können Sie mit The Mom Test-Fragen validieren:</p><ul><li>Wann hast du dich zuletzt beworben?</li><li>Wie hast du damals deinen Lebenslauf geändert?</li><li>Welcher Abschnitt war am schwersten zu schreiben?</li><li>Wie beurteilst du nach der Änderung, ob er gut genug ist?</li></ul><p>So verbinden sich die Methoden:</p><ul><li>JTBD hilft Ihnen, die Bedarfshypothese zu definieren</li><li>The Mom Test hilft Ihnen, die Hypothese durch Interviews zu validieren</li></ul><h2 id="_9-die-h-auml-ufigsten-fehler-bei-nutzerinterviews" tabindex="-1">9. Die häufigsten Fehler bei Nutzerinterviews <a class="header-anchor" href="#_9-die-h-auml-ufigsten-fehler-bei-nutzerinterviews" aria-label="Permalink to “9. Die h&amp;auml;ufigsten Fehler bei Nutzerinterviews”">​</a></h2><h3 id="_9-1-das-interview-zur-produktvorstellung-machen" tabindex="-1">9.1 Das Interview zur Produktvorstellung machen <a class="header-anchor" href="#_9-1-das-interview-zur-produktvorstellung-machen" aria-label="Permalink to “9.1 Das Interview zur Produktvorstellung machen”">​</a></h3><p>Wenn Sie zu viel über Ihre eigene Idee erzählen, fängt der andere leicht an, Ihnen zuzustimmen, anstatt Ihnen die reale Situation zu schildern.</p><h3 id="_9-2-nur-bekannte-interviewen" tabindex="-1">9.2 Nur Bekannte interviewen <a class="header-anchor" href="#_9-2-nur-bekannte-interviewen" aria-label="Permalink to “9.2 Nur Bekannte interviewen”">​</a></h3><p>Bekannte können zwar sprechen, neigen aber eher zur Ermutigung. Sie müssen mindestens einige Personen einbeziehen, die näher an echten Nutzern sind.</p><h3 id="_9-3-zu-fr-uuml-h-nach-funktionen-fragen" tabindex="-1">9.3 Zu früh nach Funktionen fragen <a class="header-anchor" href="#_9-3-zu-fr-uuml-h-nach-funktionen-fragen" aria-label="Permalink to “9.3 Zu fr&amp;uuml;h nach Funktionen fragen”">​</a></h3><p>Wenn Sie das Problem noch nicht verstanden haben und bereits nach Buttons, Oberflächen und Funktionsdetails fragen, betreten Sie zu früh die Lösungsphase.</p><h3 id="_9-4-ein-ich-w-uuml-rde-es-nutzen-als-validierungsergebnis-betrachten" tabindex="-1">9.4 Ein &quot;Ich würde es nutzen&quot; als Validierungsergebnis betrachten <a class="header-anchor" href="#_9-4-ein-ich-w-uuml-rde-es-nutzen-als-validierungsergebnis-betrachten" aria-label="Permalink to “9.4 Ein &quot;Ich w&amp;uuml;rde es nutzen&quot; als Validierungsergebnis betrachten”">​</a></h3><p>Interviews helfen Ihnen höchstens bei der Richtungsbewertung, sie sind keine abgeschlossene Validierung. Echte Validierung erfordert letztlich, dass Nutzer bereit sind, echte Kosten auf sich zu nehmen: Zeit, Wechselaufwand, Testverhalten oder sogar Bezahlung.</p><h3 id="_9-5-nach-dem-interview-nicht-zusammenfassen" tabindex="-1">9.5 Nach dem Interview nicht zusammenfassen <a class="header-anchor" href="#_9-5-nach-dem-interview-nicht-zusammenfassen" aria-label="Permalink to “9.5 Nach dem Interview nicht zusammenfassen”">​</a></h3><p>Wenn Sie nach dem Gespräch die Informationen einfach liegen lassen, werden sie schnell zu vagen Eindrücken. Am besten sofort zusammenfassen:</p><ul><li>Häufig erwähnte Probleme</li><li>Emotionswörter aus Nutzerzitaten</li><li>Aktuelle Alternativlösungen</li><li>Bereits aufgewendete Kosten</li><li>Ihre eigenen neuen Einschätzungen</li></ul><h2 id="_10-eine-fragenliste-die-sie-direkt-kopieren-k-ouml-nnen" tabindex="-1">10. Eine Fragenliste, die Sie direkt kopieren können <a class="header-anchor" href="#_10-eine-fragenliste-die-sie-direkt-kopieren-k-ouml-nnen" aria-label="Permalink to “10. Eine Fragenliste, die Sie direkt kopieren k&amp;ouml;nnen”">​</a></h2><p>Wenn Sie schnell starten möchten, hier eine ausreichend universelle Frageliste.</p><h3 id="er-ouml-ffnungsfragen" tabindex="-1">Eröffnungsfragen <a class="header-anchor" href="#er-ouml-ffnungsfragen" aria-label="Permalink to “Er&amp;ouml;ffnungsfragen”">​</a></h3><ul><li>Wann hatten Sie das letzte Mal dieses Problem?</li><li>Was genau ist damals passiert?</li></ul><h3 id="verhaltensfragen" tabindex="-1">Verhaltensfragen <a class="header-anchor" href="#verhaltensfragen" aria-label="Permalink to “Verhaltensfragen”">​</a></h3><ul><li>Wie haben Sie es damals gelöst?</li><li>Warum haben Sie sich für diese Vorgehensweise entschieden?</li></ul><h3 id="kostenfragen" tabindex="-1">Kostenfragen <a class="header-anchor" href="#kostenfragen" aria-label="Permalink to “Kostenfragen”">​</a></h3><ul><li>Wie viel Zeit oder Energie kostet Sie diese Angelegenheit normalerweise?</li><li>Haben Sie jemals Geld ausgegeben, um es zu lösen?</li></ul><h3 id="alternativl-ouml-sungsfragen" tabindex="-1">Alternativlösungsfragen <a class="header-anchor" href="#alternativl-ouml-sungsfragen" aria-label="Permalink to “Alternativl&amp;ouml;sungsfragen”">​</a></h3><ul><li>Haben Sie andere Tools oder Methoden ausprobiert?</li><li>Warum haben Sie sie nicht weiter verwendet?</li></ul><h3 id="abschlussfragen" tabindex="-1">Abschlussfragen <a class="header-anchor" href="#abschlussfragen" aria-label="Permalink to “Abschlussfragen”">​</a></h3><ul><li>Wenn Sie dieses Problem in Zukunft wieder haben: Wie sollte die ideale Lösung Ihrer Meinung nach aussehen?</li></ul><p>Beachten Sie: Diese Abschlussfrage könnte gestellt werden, aber am besten später im Interview. Denn vorher benötigen Sie eher Fakten als Wünsche.</p><h2 id="_11-zusammenfassung" tabindex="-1">11. Zusammenfassung <a class="header-anchor" href="#_11-zusammenfassung" aria-label="Permalink to “11. Zusammenfassung”">​</a></h2><p>Der wichtigste Beitrag von The Mom Test ist nicht, Ihnen eine &quot;bessere Gesprächsführung&quot; beizubringen, sondern Ihnen eine klarere Urteilsmethode zu geben:</p><ul><li>Nicht zu schnell das Lob anderer für Ihre Idee glauben</li><li>&quot;Ich würde es nutzen, wenn es gäbe&quot; nicht als echten Bedarf betrachten</li><li>Das Interview nicht zu einer Suche nach Bestätigung machen</li></ul><p>Echt wertvolle Interviews sollten sich auf Folgendes konzentrieren:</p><ul><li>Das letzte echte Erlebnis des Nutzers</li><li>Wie er aktuell damit umgeht</li><li>Welche Kosten er bereits auf sich genommen hat</li><li>Wo er offensichtlich Unbehagen verspürt</li></ul><p>Wenn Sie anfangen, so zu fragen, sind die Informationen zwar manchmal weniger schmeichelhaft, aber meist nützlicher. Bei der Produktentwicklung gilt: <strong>Nützliche Wahrheiten sind immer wichtiger als schöne Ermutigungen.</strong></p><p><a id="mom-ai"></a></p><h2 id="_12-wie-sie-ai-bei-nutzerinterviews-unterst-uuml-tzen-lassen" tabindex="-1"><a href="#top-mom">12. Wie Sie AI bei Nutzerinterviews unterstützen lassen</a> <a class="header-anchor" href="#_12-wie-sie-ai-bei-nutzerinterviews-unterst-uuml-tzen-lassen" aria-label="Permalink to “12. Wie Sie AI bei Nutzerinterviews unterst&amp;uuml;tzen lassen”">​</a></h2><p>The Mom Test ist im Kern eine Methode zum &quot;Sprechen mit echten Menschen&quot;, daher kann AI reale Interviews nicht ersetzen. Aber AI eignet sich hervorragend als Unterstützung vor, während und nach Interviews, besonders um die Einstiegshürde für Einsteiger zu senken.</p><h3 id="_12-1-ai-helfen-lassen-leicht-nutzlose-fragen-umzuschreiben" tabindex="-1">12.1 AI helfen lassen, &quot;leicht nutzlose&quot; Fragen umzuschreiben <a class="header-anchor" href="#_12-1-ai-helfen-lassen-leicht-nutzlose-fragen-umzuschreiben" aria-label="Permalink to “12.1 AI helfen lassen, &quot;leicht nutzlose&quot; Fragen umzuschreiben”">​</a></h3><p>Viele wissen, dass sie nicht fragen sollten: &quot;Was hältst du von meiner Idee?&quot; Aber wenn sie anfangen zu sprechen, kehren sie automatisch zu solchen Sätzen zurück. Sie können zunächst Ihre geplanten Interview-Fragen an AI übergeben und sie umschreiben lassen:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Hier sind die Fragen, die ich bei Nutzerinterviews stellen m&amp;ouml;chte:</span></span>
<span class="line"><span>[Ihre Fragen einf&amp;uuml;gen]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Bitte schreibe sie nach den Prinzipien von The Mom Test um:</span></span>
<span class="line"><span>1. Meinungsfragen entfernen</span></span>
<span class="line"><span>2. Zukunfts-Hypothese-Fragen entfernen</span></span>
<span class="line"><span>3. Stattdessen auf vergangenes echtes Verhalten, bestehende Alternativl&amp;ouml;sungen und bereits aufgewendete Kosten konzentrieren</span></span>
<span class="line"><span>4. Am Ende in eine Liste von 8-10 direkt verwendbaren Interview-Fragen zusammenfassen</span></span></code></pre></div><p>Eine sehr anfängerhafte Eingabe ist ebenfalls möglich:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Ich m&amp;ouml;chte Nutzer fragen:</span></span>
<span class="line"><span>1. Was h&amp;auml;ltst du davon, wenn ich ein AI-Lebenslauf-Tool entwickle?</span></span>
<span class="line"><span>2. W&amp;uuml;rdest du es nutzen?</span></span>
<span class="line"><span>3. W&amp;auml;rst du bereit, daf&amp;uuml;r zu bezahlen?</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Bitte schreibe die Fragen besser.</span></span></code></pre></div><p>AI könnte folgende nützliche Ausgabe liefern:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Umgeschriebene Fragen:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Wann hast du zuletzt deinen Lebenslauf ge&amp;auml;ndert?</span></span>
<span class="line"><span>2. Warum musstest du ihn &amp;auml;ndern?</span></span>
<span class="line"><span>3. Wie hast du ihn ge&amp;auml;ndert?</span></span>
<span class="line"><span>4. Welcher Schritt hat am meisten Zeit gekostet?</span></span>
<span class="line"><span>5. Hast du jemanden gebeten, dir beim Gegenlesen zu helfen?</span></span>
<span class="line"><span>6. Hast du jemals Geld oder viel Zeit f&amp;uuml;r die Lebenslauf&amp;auml;nderung aufgewendet?</span></span></code></pre></div><p>Diese Ausgabe ist sehr hilfreich, denn sie ändert Ihre ursprünglichen &quot;nach Meinungen fragenden&quot; Fragen direkt in &quot;nach echtem Verhalten fragende&quot; Fragen.</p><h3 id="_12-2-ai-helfen-lassen-verschiedene-interview-leitf-auml-den-f-uuml-r-verschiedene-zielgruppen-zu-erstellen" tabindex="-1">12.2 AI helfen lassen, verschiedene Interview-Leitfäden für verschiedene Zielgruppen zu erstellen <a class="header-anchor" href="#_12-2-ai-helfen-lassen-verschiedene-interview-leitf-auml-den-f-uuml-r-verschiedene-zielgruppen-zu-erstellen" aria-label="Permalink to “12.2 AI helfen lassen, verschiedene Interview-Leitf&amp;auml;den f&amp;uuml;r verschiedene Zielgruppen zu erstellen”">​</a></h3><p>Bei derselben Richtung sind die Interview-Schwerpunkte für verschiedene Zielgruppen unterschiedlich. Studierende, HR-Profis, Freiberufler haben völlig unterschiedliche Anliegen. Sie können AI bitten, für jede Zielgruppe einen eigenen Leitfaden zu erstellen:</p><ul><li>Für neue Nutzer: Schwerpunkt auf dem letzten echten Erlebnis</li><li>Für Power-User: Schwerpunkt auf Alternativlösungen und Schmerzintensität</li><li>Für zahlende Nutzer: Schwerpunkt auf bereits aufgewendeten Kosten</li></ul><p>So haben Sie beim echten Gespräch mehr Rhythmus und stellen nicht jedem dieselben Fragen.</p><p>Sie könnten direkt so eingeben:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Ich werde mit zwei Arten von Menschen sprechen:</span></span>
<span class="line"><span>1. Studierende, die zum ersten Mal ein Praktikum suchen</span></span>
<span class="line"><span>2. &amp;Auml;ltere Kommilitonen, die bereits vielen beim Lebenslauf geholfen haben</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Bitte gib mir jeweils einen Interview-Leitfaden mit 6 Fragen pro Zielgruppe.</span></span></code></pre></div><p>AI könnte ausgeben:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>F&amp;uuml;r Studierende:</span></span>
<span class="line"><span>1. Wann hast du dich zuletzt auf ein Praktikum beworben?</span></span>
<span class="line"><span>2. Welcher Schritt war am schwierigsten?</span></span>
<span class="line"><span>3. Woher wei&amp;szligt du, ob dein Lebenslauf bewerbungsbereit ist?</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>F&amp;uuml;r &amp;auml;ltere Kommilitonen:</span></span>
<span class="line"><span>1. Wann hast du zuletzt jemandem beim Lebenslauf geholfen?</span></span>
<span class="line"><span>2. Welche offensichtlichen Probleme siehst du am h&amp;auml;ufigsten?</span></span>
<span class="line"><span>3. Woran scheitern j&amp;uuml;ngere Kommilitonen am meisten?</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>So müssen Sie nicht von null anfangen und die Interview-Vorbereitung wird deutlich entspannter.</p><h3 id="_12-3-ai-beim-ordnen-von-interview-aufzeichnungen-helfen-lassen" tabindex="-1">12.3 AI beim Ordnen von Interview-Aufzeichnungen helfen lassen <a class="header-anchor" href="#_12-3-ai-beim-ordnen-von-interview-aufzeichnungen-helfen-lassen" aria-label="Permalink to “12.3 AI beim Ordnen von Interview-Aufzeichnungen helfen lassen”">​</a></h3><p>Nach dem Interview ist das häufigste Problem nicht &quot;keine Informationen&quot;, sondern &quot;Informationen sind zu verstreut&quot;. AI eignet sich hervorragend, um fragmentierte Gespräche in strukturierte Notizen zu ordnen:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Hier sind meine Interview-Aufzeichnungen mit 3 Nutzern.</span></span>
<span class="line"><span>Bitte ordne sie aus der Perspektive von The Mom Test:</span></span>
<span class="line"><span>1. Was sind Fakten, was sind nur Meinungen</span></span>
<span class="line"><span>2. Was war das letzte echte Verhalten des Nutzers</span></span>
<span class="line"><span>3. Was ist die aktuelle Alternativl&amp;ouml;sung</span></span>
<span class="line"><span>4. Welche Zeit-, Geld- oder Energiekosten hat der Nutzer bereits aufgewendet</span></span>
<span class="line"><span>5. Welche Probleme wurden wiederholt erw&amp;auml;hnt</span></span>
<span class="line"><span>6. Welche &amp;Auml;u&amp;szlig;erungen klingen positiv, sind aber nicht ausreichend belegt</span></span></code></pre></div><p>Dieser Schritt ist besonders wertvoll, denn er hilft, &quot;gut klingende&quot; von &quot;wirklich urteilsfähigen&quot; Inhalten zu trennen.</p><p>Eine einfache Eingabe könnte so aussehen:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Hier ist meine Aufzeichnung nach einem Gespr&amp;auml;ch mit einem Nutzer:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- Sie sagte, sie w&amp;uuml;rde ein Tool ausprobieren, wenn es eines g&amp;auml;be</span></span>
<span class="line"><span>- Letzte Woche hat sie einen Abend damit verbracht, ihren Lebenslauf zu &amp;auml;ndern</span></span>
<span class="line"><span>- Aktuell l&amp;auml;sst sie haupts&amp;auml;chlich Freunde gegenlesen</span></span>
<span class="line"><span>- Sie sagte, das Schwerste sei, nicht zu wissen, wann der Lebenslauf &quot;abschickbereit&quot; ist</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Bitte teile mir mit, was Meinungen und was Fakten sind.</span></span></code></pre></div><p>AI könnte ausgeben:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Meinungen:</span></span>
<span class="line"><span>- Sie w&amp;uuml;rde ein Tool ausprobieren, wenn es eines g&amp;auml;be</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Fakten:</span></span>
<span class="line"><span>- Letzte Woche einen Abend f&amp;uuml;r die Lebenslauf&amp;auml;nderung aufgewendet</span></span>
<span class="line"><span>- Aktuelle Alternativl&amp;ouml;sung: Freunde bitten, gegenzulesen</span></span>
<span class="line"><span>- Hauptschmerz: Nicht wissen, wann man &quot;abschicken kann&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>F&amp;uuml;r die Bedarfserkenntnis relevante Punkte:</span></span>
<span class="line"><span>- Das Problem ist k&amp;uuml;rzlich aufgetreten</span></span>
<span class="line"><span>- Der Nutzer hat bereits erhebliche Zeitkosten investiert</span></span>
<span class="line"><span>- Die aktuelle L&amp;ouml;sung ist von anderen abh&amp;auml;ngig und instabil</span></span></code></pre></div><p>Diese Ausgabe zeigt Einsteigern sehr deutlich: Welche Aussagen für Urteile verwendet werden können und welche nur zur Kenntnis genommen werden sollten.</p><h3 id="_12-4-ai-zun-auml-chst-eine-leichte-webrecherche-durchf-uuml-hren-lassen" tabindex="-1">12.4 AI zunächst eine leichte Webrecherche durchführen lassen <a class="header-anchor" href="#_12-4-ai-zun-auml-chst-eine-leichte-webrecherche-durchf-uuml-hren-lassen" aria-label="Permalink to “12.4 AI zun&amp;auml;chst eine leichte Webrecherche durchf&amp;uuml;hren lassen”">​</a></h3><p>Wenn Sie noch nicht mit Interviews begonnen haben, können Sie AI zunächst eine sehr leichte externe Recherche durchführen lassen:</p><ul><li>Wie wird in öffentlichen Communitys über dieses Problem geklagt</li><li>Was wird an bestehenden Tools am meisten kritisiert</li><li>Ob Nutzer bereits für ähnliche Probleme bezahlen</li><li>Welche Alternativlösungen auf dem Markt bereits existieren</li></ul><p>Diese Informationen können echte Interviews nicht ersetzen, helfen aber, schneller in den Zustand zu kommen, in dem Sie wissen, wo Sie ansetzen sollten.</p><p>Ein einfacher Prompt könnte lauten:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Bitte recherchiere f&amp;uuml;r mich:</span></span>
<span class="line"><span>&quot;Was beklagen Studierende am h&amp;auml;ufigsten beim Umschreiben von Lebensl&amp;auml;ufen&quot;</span></span>
<span class="line"><span>Fasse es in 5 h&amp;auml;ufigste Beschwerden zusammen, in sehr einfachen Worten.</span></span></code></pre></div><p>AI könnte ausgeben:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>H&amp;auml;ufige Beschwerden:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Nicht wissen, was im Lebenslauf stehen sollte</span></span>
<span class="line"><span>2. F&amp;uuml;r jede Stelle muss man ihn neu anpassen, das ist zu anstrengend</span></span>
<span class="line"><span>3. Nach vielen &amp;Uuml;berarbeitungen immer noch unsicher, ob es gut ist</span></span>
<span class="line"><span>4. Niemand gibt verl&amp;auml;ssliches Feedback</span></span>
<span class="line"><span>5. Man hat st&amp;auml;ndig das Gef&amp;uuml;hl, nicht bereit zu sein, also schiebt man es auf</span></span></code></pre></div><p>Der Wert solcher Ergebnisse liegt darin, dass sie Ihnen den Einstiegspunkt für Interviews erleichtern.</p><h3 id="_12-5-ai-als-interview-nachbereitungs-coach-nutzen" tabindex="-1">12.5 AI als &quot;Interview-Nachbereitungs-Coach&quot; nutzen <a class="header-anchor" href="#_12-5-ai-als-interview-nachbereitungs-coach-nutzen" aria-label="Permalink to “12.5 AI als &quot;Interview-Nachbereitungs-Coach&quot; nutzen”">​</a></h3><p>Sie können auch eine gerade abgeschlossene Interview-Aufzeichnung an AI übergeben und sie bitten, Sie zu kritisieren:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Hier ist eine meiner Nutzer-Interview-Aufzeichnungen.</span></span>
<span class="line"><span>Bitte hilf mir aus der Perspektive von The Mom Test bei der Nachbereitung:</span></span>
<span class="line"><span>1. Bei welchen Fragen suchte ich zu sehr nach Best&amp;auml;tigung</span></span>
<span class="line"><span>2. Welche Fragen hatten offensichtliche Lenkungen</span></span>
<span class="line"><span>3. Wo h&amp;auml;tte ich weiter nach Fakten fragen k&amp;ouml;nnen</span></span>
<span class="line"><span>4. Wenn ich noch einmal k&amp;ouml;nnte, wie k&amp;ouml;nnte dieses Gespr&amp;auml;ch besser gef&amp;uuml;hrt werden</span></span></code></pre></div><p>Das ist besonders hilfreich für Einsteiger, denn Sie entwickeln schneller ein Gespür dafür, ob Sie &quot;Beweise sammeln&quot; oder &quot;Ermutigung sammeln&quot;.</p><h2 id="assignments" tabindex="-1">Assignments <a class="header-anchor" href="#assignments" aria-label="Permalink to “Assignments”">​</a></h2><p>Bitte bearbeiten Sie die folgenden Aufgaben basierend auf dem obigen Inhalt:</p><ol><li>Wählen Sie eine Produktrichtung, an der Sie kürzlich denken, und schreiben Sie zunächst 5 &quot;leicht nutzlose&quot; Fragen, die Sie ursprünglich gestellt hätten</li><li>Schreiben Sie diese 5 Fragen im Stil von The Mom Test um</li><li>Finden Sie 3 potenzielle Nutzer und fragen Sie mindestens einmal: &quot;Wann hatten Sie das letzte Mal dieses Problem?&quot;</li><li>Nach dem Interview ordnen Sie 4 Arten von Informationen: Echtes Verhalten, Alternativlösungen, bereits aufgewendete Kosten, wiederkehrende Schwierigkeiten</li></ol><h2 id="weiterf-uuml-hrende-literatur" tabindex="-1">Weiterführende Literatur <a class="header-anchor" href="#weiterf-uuml-hrende-literatur" aria-label="Permalink to “Weiterf&amp;uuml;hrende Literatur”">​</a></h2><ul><li><a href="https://momtestbook.com/" target="_blank" rel="noreferrer">The Mom Test Offizielle Website</a></li><li><a href="https://www.robfitz.com/the-mom-test/" target="_blank" rel="noreferrer">Rob Fitzpatrick: The Mom Test</a></li></ul>`,188))])}}});export{g as __pageData,b as default};
